"""Is Graph Bipartite? — two-colour the graph with BFS.

A conflict between a node and an already-coloured neighbour means an odd cycle.

Time: O(V + E)   Space: O(V)
"""
from collections import deque
from typing import List


class Solution:
    def isBipartite(self, graph: List[List[int]]) -> bool:
        colour = {}
        for start in range(len(graph)):
            if start in colour:
                continue
            colour[start] = 0
            queue = deque([start])
            while queue:
                node = queue.popleft()
                for nxt in graph[node]:
                    if nxt not in colour:
                        colour[nxt] = colour[node] ^ 1
                        queue.append(nxt)
                    elif colour[nxt] == colour[node]:
                        return False
        return True
